import React, { useEffect, useState } from 'react';
import { BarChart3, Database, Zap, FileText } from 'lucide-react';
import MetricsCard from '../components/MetricsCard';
import { api } from '../api/client';

const Dashboard = () => {
    const [metrics, setMetrics] = useState([
        { title: 'Total Articles', value: '1,240', change: '+12%', icon: Database },
        { title: 'Avg Confidence', value: '98.5%', change: '+0.5%', icon: Zap },
        { title: 'RAG Queries', value: '342', change: '+24%', icon: BarChart3 },
        { title: 'Reports Generated', value: '56', change: 'N/A', icon: FileText },
    ]);

    useEffect(() => {
        // In a real app, fetch metrics from API
        // api.getMetrics().then(...)
    }, []);

    const handleReportGeneration = async () => {
        try {
            const response = await api.generatePdfReport();
            // Create blob link to download
            const url = window.URL.createObjectURL(new Blob([response.data]));
            const link = document.createElement('a');
            link.href = url;
            link.setAttribute('download', 'ai_news_report.pdf');
            document.body.appendChild(link);
            link.click();
            link.remove();
        } catch (error) {
            console.error("Failed to generate report:", error);
        }
    };

    return (
        <div className="p-8 space-y-8">
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-3xl font-bold text-gray-800">Dashboard</h1>
                    <p className="text-gray-500 mt-1">Overview of AI News Intelligence System</p>
                </div>
                <button
                    onClick={handleReportGeneration}
                    className="px-6 py-3 bg-gradient-to-r from-primary to-gradient-pink text-white rounded-xl shadow-lg hover:shadow-xl transition-all font-medium"
                >
                    Generate Report
                </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                {metrics.map((m, idx) => (
                    <MetricsCard key={idx} {...m} />
                ))}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
                    <h3 className="text-lg font-bold text-gray-800 mb-4">Recent Activity</h3>
                    <div className="space-y-4">
                        {[1, 2, 3].map((i) => (
                            <div key={i} className="flex items-center justify-between p-4 bg-gray-50 rounded-xl">
                                <div className="flex items-center space-x-3">
                                    <div className="w-2 h-2 bg-green-500 rounded-full" />
                                    <span className="text-sm font-medium text-gray-700">Classification Task Completed</span>
                                </div>
                                <span className="text-xs text-gray-400">2 mins ago</span>
                            </div>
                        ))}
                    </div>
                </div>

                <div className="bg-gradient-to-br from-primary to-sidebar-purple p-6 rounded-2xl shadow-lg text-white relative overflow-hidden">
                    <div className="relative z-10">
                        <h3 className="text-xl font-bold mb-2">System Status</h3>
                        <p className="text-white/80 mb-6">All systems operational. Vertex AI connected.</p>
                        <div className="flex items-center space-x-2">
                            <div className="w-3 h-3 bg-green-400 rounded-full animate-pulse" />
                            <span className="font-medium">Online</span>
                        </div>
                    </div>
                    {/* Decorative circles */}
                    <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full -mr-10 -mt-10 blur-2xl" />
                    <div className="absolute bottom-0 left-0 w-24 h-24 bg-white/10 rounded-full -ml-10 -mb-10 blur-xl" />
                </div>
            </div>
        </div>
    );
};

export default Dashboard;
